RESPALDO = ".examen_grande1_respaldo"
PROHIBIDO = ("memory/", "cartuchos/", "checkpoints/", "data/", ".git/")


def sha(b):
    return hashlib.sha256(b).hexdigest()


def leer(p):
    try:
        with open(p, "rb") as fh:
            return fh.read()
    except OSError:
        return None


def contenido(p):
    return zlib.decompress(base64.b64decode(ARCH[p]["z"]))


def comprobar_raiz():
    if not (os.path.isdir("src/web") and os.path.exists("lab/iter222/correr.py")):
        sys.exit("[!] Ejecuta este parche en la carpeta del proyecto LCM con LCM 2.22 instalado (falta lab/iter222/correr.py).")


def estado():
    """(pendientes, ya_instalados, conflictos)"""
    pend, hechos, conf = [], [], []
    for p in NUEVOS + MODIF:
        act = leer(p)
        if act is not None and sha(act) == ARCH[p]["sha"]:
            hechos.append(p)
        elif p in MODIF and act is not None and sha(act) != ORIGINAL[p]:
            conf.append(p)
        else:
            pend.append(p)
    return pend, hechos, conf


def plan():
    comprobar_raiz()
    pend, hechos, conf = estado()
    print("LCM — EXAMEN GRANDE 1: PLAN")
    for p in NUEVOS + MODIF:
        marca = "YA ESTÁ " if p in hechos else ("CONFLICTO" if p in conf else ("CAMBIAR " if (p in MODIF or os.path.exists(p)) else "CREAR   "))
        print(f"  {marca} {p}")
    for p in BORRAR:
        if os.path.exists(p):
            print(f"  RETIRAR  {p}")
    if conf:
        print("\n[!] Estos archivos no coinciden con LCM 2.21 tal como lo instaló parche_lcm221.py:")
        for p in conf:
            print("     ", p)
        print("    Se sustituirían completos. Revisa las diferencias y, si estás de acuerdo, usa --aplicar --forzar.")
    print("Nunca se tocan: memory/, cartuchos/, checkpoints/, data/, modelos entrenados.")
    return conf


def aplicar(forzar=False):
    comprobar_raiz()
    pend, hechos, conf = estado()
    if conf and not forzar:
        plan()
        sys.exit(1)
    if not pend and not conf and not any(os.path.exists(p) for p in BORRAR):
        print("[OK] El examen grande 1 ya estaba instalado; no hay nada que hacer.")
        return
    marca = time.strftime("%Y%m%d-%H%M%S")
    dest = os.path.join(RESPALDO, marca)
    os.makedirs(dest, exist_ok=True)
    registro = {"creados": [], "cambiados": []}
    for p in pend + conf:
        assert not p.startswith(PROHIBIDO), p
        act = leer(p)
        if act is not None:
            os.makedirs(os.path.dirname(os.path.join(dest, p)) or dest, exist_ok=True)
            with open(os.path.join(dest, p), "wb") as fh:
                fh.write(act)
            registro["cambiados"].append(p)
        else:
            registro["creados"].append(p)
        os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
        with open(p, "wb") as fh:
            fh.write(contenido(p))
        print(("  CAMBIADO " if act is not None else "  CREADO   ") + p)
    registro["borrados"] = []
    for p in BORRAR:
        act = leer(p)
        if act is not None:
            os.makedirs(os.path.dirname(os.path.join(dest, p)) or dest, exist_ok=True)
            with open(os.path.join(dest, p), "wb") as fh:
                fh.write(act)
            os.remove(p)
            registro["borrados"].append(p)
            print("  RETIRADO " + p)
    with open(os.path.join(dest, "registro.json"), "w", encoding="utf-8") as fh:
        json.dump(registro, fh, ensure_ascii=False, indent=1)
    print(f"[OK] Instalados {len(pend) + len(conf)} archivos. Copia reversible: {dest}")
    print("Sin cambios en memory/, cartuchos/, checkpoints/ ni data/.")
    print("Pruebas:    python -m pytest -q")
    print("Examen:    python -m lab.aprender.banco grande1b texto    (2.22 = 82,7 %; examen corregido)")
    print("           python -m lab.aprender.banco grande1b frases   (2.22 = 82,1 %)")
    print("Diagnóstico: python -m lab.grande1.diagnostico   (en qué paso se rompe cada fallo)")


def verificar():
    comprobar_raiz()
    mal = [p for p in NUEVOS + MODIF if leer(p) is None or sha(leer(p)) != ARCH[p]["sha"]]
    if mal:
        print("[!] No coinciden con el parche:")
        for p in mal:
            print("     ", p)
        sys.exit(1)
    try:
        import importlib
        sys.path.insert(0, os.getcwd())
        importlib.import_module("src.nucleo20")
        importlib.import_module("src.nucleo20.vista"); importlib.import_module("src.nucleo20.coloquial"); importlib.import_module("src.apps"); importlib.import_module("src.nucleo20.calculo"); importlib.import_module("src.nucleo20.relaciones"); importlib.import_module("src.nucleo20.lectura"); importlib.import_module("src.nucleo20.crear"); importlib.import_module("src.nucleo20.secuencias"); importlib.import_module("src.nucleo20.escuela")
    except Exception as e:                                                    # noqa
        sys.exit(f"[!] Los archivos están, pero el código no se importa: {e!r}")
    print(f"[OK] Integridad del examen grande 1 correcta ({len(NUEVOS) + len(MODIF)} archivos).")


def revertir():
    comprobar_raiz()
    if not os.path.isdir(RESPALDO) or not os.listdir(RESPALDO):
        sys.exit("[!] No hay ninguna copia que revertir.")
    ult = sorted(os.listdir(RESPALDO))[-1]
    dest = os.path.join(RESPALDO, ult)
    with open(os.path.join(dest, "registro.json"), encoding="utf-8") as fh:
        registro = json.load(fh)
    for p in registro["cambiados"]:
        shutil.copyfile(os.path.join(dest, p), p)
        print("  RESTAURADO " + p)
    for p in registro["creados"]:
        if os.path.exists(p):
            os.remove(p)
            print("  BORRADO    " + p)
    for p in registro.get("borrados", []):
        shutil.copyfile(os.path.join(dest, p), p)
        print("  RESTAURADO " + p)
    for d in ("src/apps/__pycache__", "src/apps", "src/nucleo20/cartillas", "src/nucleo20/__pycache__", "src/nucleo20", "lab/__pycache__", "lab"):
        if os.path.isdir(d) and not [x for x in os.listdir(d) if x != "__pycache__"]:
            shutil.rmtree(d, ignore_errors=True)
    shutil.rmtree(dest, ignore_errors=True)
    print(f"[OK] Revertida la instalación {ult}.")


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="LCM 2.22 · Aprender de un texto")
    g = ap.add_mutually_exclusive_group(required=True)
    g.add_argument("--plan", action="store_true"); g.add_argument("--aplicar", action="store_true")
    g.add_argument("--verificar", action="store_true"); g.add_argument("--revertir", action="store_true")
    ap.add_argument("--forzar", action="store_true", help="con --aplicar: sustituye también archivos que no coinciden con LCM 2.21")
    a = ap.parse_args()
    if a.plan:
        plan()
    elif a.aplicar:
        aplicar(a.forzar)
    elif a.verificar:
        verificar()
    else:
        revertir()
